import type {LibraryWeekdayHours} from './publicLibrarySources.js';
export type VerificationEvidence = {id:string;content:string;url?:string;urls?:string[];title?:string;capturedOn?:string;libraryWeekdayHours?:LibraryWeekdayHours};
export type VerificationCandidate = {answer:string;status:string;citations:any[];activity?:any[];grounding?:Record<string,any>;suggestedQuestions?:string[];proposedAction?:any;[key:string]:any};
export type VerificationContext = {question:string;candidate:VerificationCandidate;evidence:VerificationEvidence[];deadline:number;feedback?:string[]};
export type VerificationProgress = {kind:string;label:string;detail:string;status:'running'|'complete'|'unavailable'};
export type VerificationCheckContext = VerificationContext & {attempt:number;afterVerifiedPartial?:boolean;previousMissingRequestedDetails?:string[]};
type VerificationEvidenceLoader = (options:{attempt:number;deadline:number;feedback?:string[];previousFailure?:string})=>Promise<VerificationEvidence[]>;
export function runAnswerVerification(options:{question:string;initialAnswer:VerificationCandidate;loadEvidence:VerificationEvidenceLoader;loadDeeperEvidence?:VerificationEvidenceLoader;verify:(context:VerificationCheckContext)=>Promise<{ok:boolean;reason?:string;feedback?:string[];missingRequestedDetails?:string[]}>;repair:(context:VerificationCheckContext)=>Promise<VerificationCandidate>;onProgress?:(step:VerificationProgress)=>void;allowDeeperReview?:boolean;deferTerminalProgress?:boolean;previousChecks?:number;maxChecks?:3|4;canExtendReview?:()=>boolean;lookForMissingPublicDetails?:()=>boolean;hasUnreadPublicLead?:()=>boolean;priorVerifiedPartial?:{candidate:VerificationCandidate;missing:string[]};hasLocalCorrection?:boolean;deadline?:number}):Promise<VerificationCandidate>;
export function normalizeMissingDetails(details:unknown):string[]|null;
export function publicEvidenceInterruption(reason?:string):boolean;
export function unverifiedAnswer(question:string,candidate:VerificationCandidate,activity:VerificationProgress[],attempts:number,reason:string):VerificationCandidate;
export function verificationStopActivity(question:string,cause?:'time_budget'|'source_read_time_limit'|'reviewer_unavailable'|'repair_unavailable'|'no_usable_evidence'|'no_safe_continuation'|'verification_limit'):VerificationProgress;
